steps.command:
sbx run <<'EOF'
set -e
mkdir -p /tmp/base
mount -o ro /dev/vda /tmp/base
mkdir -p /tmp/ov/etc-upper /tmp/ov/etc-work /tmp/ov/var-upper /tmp/ov/var-work /tmp/ov/usr-upper /tmp/ov/usr-work /tmp/ov/run-upper /tmp/ov/run-work
mount -t overlay overlay -o lowerdir=/tmp/base/etc,upperdir=/tmp/ov/etc-upper,workdir=/tmp/ov/etc-work /etc
mount -t overlay overlay -o lowerdir=/tmp/base/var,upperdir=/tmp/ov/var-upper,workdir=/tmp/ov/var-work /var
mount -t overlay overlay -o lowerdir=/tmp/base/usr,upperdir=/tmp/ov/usr-upper,workdir=/tmp/ov/usr-work /usr
mount -t overlay overlay -o lowerdir=/tmp/base/run,upperdir=/tmp/ov/run-upper,workdir=/tmp/ov/run-work /run

cat > /workspace/setup_nginx.sh <<'SETUP_SCRIPT'
#!/bin/bash
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive

apt-get update -qq
apt-get install -y -qq nginx

mkdir -p /var/www/html /var/log/nginx /etc/nginx/conf.d

cat > /etc/nginx/nginx.conf <<'NGINXCONF'
user www-data;
worker_processes auto;
pid /run/nginx.pid;
include /etc/nginx/modules-enabled/*.conf;

events {
    worker_connections 768;
}

http {
    sendfile on;
    tcp_nopush on;
    keepalive_timeout 65;
    types_hash_max_size 2048;

    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    log_format benchmark '$remote_addr - $remote_user [$time_local] "$request" $request_method $status "$http_user_agent"';
    limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;

    access_log /var/log/nginx/access.log;
    error_log /var/log/nginx/error.log;

    gzip on;

    include /etc/nginx/conf.d/*.conf;
    include /etc/nginx/sites-enabled/*;
}
NGINXCONF

cat > /etc/nginx/conf.d/benchmark-site.conf <<'SITECONF'
server {
    listen 8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10 nodelay;

    location / {
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;

    location = /404.html {
    }
}
SITECONF

printf '%s\n' 'Welcome to the benchmark webserver' > /var/www/html/index.html
printf '%s\n' 'Page not found - Please check your URL' > /var/www/html/404.html

rm -f /etc/nginx/sites-enabled/default

mkdir -p /workspace/nginx-config
cp /etc/nginx/nginx.conf /workspace/nginx-config/nginx.conf
cp /etc/nginx/conf.d/benchmark-site.conf /workspace/nginx-config/benchmark-site.conf
cp /var/www/html/index.html /workspace/nginx-config/index.html
cp /var/www/html/404.html /workspace/nginx-config/404.html

nginx -t

nginx -s stop 2>/dev/null || true
sleep 1
nginx
sleep 1

python3 - <<'PY'
import urllib.request, urllib.error
for path in ("/", "/does-not-exist", "/404.html"):
    try:
        r = urllib.request.urlopen("http://127.0.0.1:8080" + path, timeout=5)
        code, body = r.status, r.read().decode()
    except urllib.error.HTTPError as e:
        code, body = e.code, e.read().decode()
    print(f"{path} -> {code}: {body.strip()!r}")
PY

echo "Access log location: /var/log/nginx/benchmark-access.log"
echo "--- benchmark-access.log ---"
cat /var/log/nginx/benchmark-access.log
SETUP_SCRIPT

chmod +x /workspace/setup_nginx.sh
bash /workspace/setup_nginx.sh
EOF
